sys_script_email.script:
(function runMailScript(current, template, email, email_action, event) {

    // ==========================================
    // 1. IDENTIFY THE TARGET RECORD
    // ==========================================
    var targetGr = null;
    var isApprovalAlert = false;

    if (current.getTableName() == 'sysapproval_approver') {
        targetGr = current.sysapproval.getRefRecord();
        isApprovalAlert = true; 
    } else {
        targetGr = current; 
    }
    if (!targetGr) return;

    var tableName = targetGr.getTableName();
    var reqNum = targetGr.getValue('number') || 'N/A';
    var urlReqNum = reqNum; // Determines which number goes into the Portal URL

    // Clean up ServiceNow carriage returns to prevent extra <br> tags
    var rawJustification = targetGr.getValue('justification') || 'No justification provided.';
    var cleanJustification = rawJustification.toString().trim().replace(/\r\n/g, '\n').replace(/\n{2,}/g, '<br><br>').replace(/\n/g, '<br>');

    // ==========================================
    // 2. EXTRACT CONTEXT (Batch vs Child Site)
    // ==========================================
    var identifier = ""; 
    var rowData = [];
    var sysIdToView = "";
    var isDeviation = false;
    var outstandingHtml = ""; // Will hold the bucket table for Site level

    if (tableName == 'x_birl3_clm_batch_request') {
        var pan = targetGr.getDisplayValue('pan') || 'N/A';
        var batchSegment = targetGr.getValue('segment') || 'N/A';
        var batchDesired = parseFloat(targetGr.getValue('total_desired_limit') || 0);
        var batchSafe = parseFloat(targetGr.getValue('safe_allowable_limit') || 0);

        isDeviation = (targetGr.getValue('is_deviation') == 1 || targetGr.getValue('is_deviation') == 'true');
        identifier = pan;
        sysIdToView = targetGr.getUniqueValue();

        rowData.push({label: 'Corporate PAN', value: '<strong>' + pan + '</strong>'});
        rowData.push({label: 'Segment', value: batchSegment});
        rowData.push({label: 'System Safe Limit', value: '<strong style="color: #28a745; font-size: 15px;">₹ ' + batchSafe.toLocaleString('en-IN', {minimumFractionDigits: 2}) + '</strong>'});

        var batchDesiredStyle = isDeviation ? 'color: #E65100; font-size: 15px; font-weight: bold;' : 'color: #222222; font-size: 15px; font-weight: bold;';
        rowData.push({label: 'Total Desired Limit', value: '<span style="' + batchDesiredStyle + '">₹ ' + batchDesired.toLocaleString('en-IN', {minimumFractionDigits: 2}) + '</span>'});
    } 
    else if (tableName == 'x_birl3_clm_non_trade_clr') {

        var custCodeDisplay = targetGr.getDisplayValue('customer_code') || 'Unknown Site';
        var custCodeSysId = targetGr.getValue('customer_code'); 

        var siteDesired = parseFloat(targetGr.getValue('site_desired_limit') || 0);
        var siteSafe = parseFloat(targetGr.getValue('safe_allowable_limit') || 0);

        isDeviation = (siteDesired > siteSafe);
        identifier = custCodeDisplay;
        sysIdToView = targetGr.getValue('batch_id'); 

        // Dynamically override URL Parameter: Initiators viewing their dashboard need the Parent Batch Number
        if (!isApprovalAlert) {
            urlReqNum = targetGr.batch_id.number.toString() || targetGr.getDisplayValue('batch_id');
        }

        // Fetch Extended Customer Details 
        var custName = 'N/A', city = 'N/A', zone = 'N/A', region = 'N/A', depot = 'N/A';
        var grCust = new GlideRecord('x_birl3_clm_customer');
        var cleanCustCode = custCodeSysId;

        if (custCodeSysId) {
            if (grCust.get(custCodeSysId) || grCust.get('customer_code', custCodeSysId)) { 
                cleanCustCode = grCust.getValue('customer_code'); // Guarantee String SAP Code for Outstanding Query
                custName = grCust.getValue('name') || 'N/A';
                city = grCust.getValue('city') || 'N/A';
                zone = grCust.getValue('customer_group') || 'N/A';
                region = grCust.getValue('cg4') || 'N/A';
                depot = grCust.getValue('sales_office') || 'N/A';
            }
        }

        rowData.push({label: 'Customer Name', value: '<strong>' + custName + '</strong>'});
        rowData.push({label: 'Site Code', value: custCodeDisplay}); 
        rowData.push({label: 'City / Depot', value: city + ' / ' + depot});
        rowData.push({label: 'Zone / Region', value: zone + ' / ' + region});
        rowData.push({label: 'Site Safe Limit', value: '<strong style="color: #28a745; font-size: 15px;">₹ ' + siteSafe.toLocaleString('en-IN', {minimumFractionDigits: 2}) + '</strong>'});

        var siteDesiredStyle = isDeviation ? 'color: #E65100; font-size: 15px; font-weight: bold;' : 'color: #222222; font-size: 15px; font-weight: bold;';
        rowData.push({label: 'Site Desired Limit', value: '<span style="' + siteDesiredStyle + '">₹ ' + siteDesired.toLocaleString('en-IN', {minimumFractionDigits: 2}) + '</span>'});

        // FETCH 6-MONTH OUTSTANDING BUCKETS FOR UI
        var safeL = 0, warningM = 0, criticalN = 0, toxicO = 0, totalDebt = 0;
        var outGr = new GlideRecord('x_birl3_clm_customer_outstanding');
        outGr.addQuery('customer', cleanCustCode);
        outGr.orderByDesc('sys_created_on');
        outGr.setLimit(1);
        outGr.query();

        if (outGr.next()) {
            safeL += (parseFloat(outGr.getValue('ageing0_3'))||0) + 
                     (parseFloat(outGr.getValue('ageing4_7'))||0) +
                     (parseFloat(outGr.getValue('ageing8_21'))||0) +
                     (parseFloat(outGr.getValue('ageing22_30'))||0) +
                     (parseFloat(outGr.getValue('ageing31_45'))||0) +
                     (parseFloat(outGr.getValue('ageing46_60'))||0);
            warningM += parseFloat(outGr.getValue('ageing61_75'))||0;
            criticalN += parseFloat(outGr.getValue('ageing76_90'))||0;
            toxicO += parseFloat(outGr.getValue('ageing_gt90'))||0;
        }
        totalDebt = safeL + warningM + criticalN + toxicO;

        // Build elegant Outstanding HTML Table
        outstandingHtml += '<div style="margin-bottom: 30px;">';
        outstandingHtml += '<span style="display: block; font-size: 12px; color: #003A70; text-transform: uppercase; font-weight: bold; letter-spacing: 1px; margin-bottom: 10px; border-bottom: 2px solid #f0f0f0; padding-bottom: 5px;">Historical Outstanding (6-Month Aggregation)</span>';
        outstandingHtml += '<table width="100%" cellpadding="10" cellspacing="0" border="1" style="border-collapse: collapse; border-color: #e2e8f0; font-size: 12px; text-align: center;">';
        outstandingHtml += '<tr style="background-color: #f8f9fa;">';
        outstandingHtml += '<th>Safe (0-60)</th><th>Warning (61-75)</th><th>Critical (76-90)</th><th>Toxic (>90)</th><th style="background-color: #eaeaea;">Total Debt</th>';
        outstandingHtml += '</tr><tr>';
        outstandingHtml += '<td style="color: #28a745; font-weight: bold;">₹ ' + safeL.toLocaleString('en-IN', {minimumFractionDigits: 2}) + '</td>';
        outstandingHtml += '<td style="color: #F2A900; font-weight: bold;">₹ ' + warningM.toLocaleString('en-IN', {minimumFractionDigits: 2}) + '</td>';
        outstandingHtml += '<td style="color: #E65100; font-weight: bold;">₹ ' + criticalN.toLocaleString('en-IN', {minimumFractionDigits: 2}) + '</td>';
        outstandingHtml += '<td style="color: #C8102E; font-weight: bold;">₹ ' + toxicO.toLocaleString('en-IN', {minimumFractionDigits: 2}) + '</td>';
        outstandingHtml += '<td style="background-color: #fafafa; font-weight: bold;">₹ ' + totalDebt.toLocaleString('en-IN', {minimumFractionDigits: 2}) + '</td>';
        outstandingHtml += '</tr></table></div>';

    } else {
        return; 
    }

    // ==========================================
    // 3. IDENTIFY EMAIL PURPOSE & SET ROUTING
    // ==========================================
    var notifName = email_action ? email_action.name.toString() : '';

    var subjectLine = "";
    var headerTitle = "";
    var introText = "";
    var themeAccent = "#003A70"; // UltraTech Navy Blue
    var showCommentBlock = false;

    // Default Routing (For Tracking/Viewing)
    var portalPage = "uclm_non_trade_view_request"; 
    var buttonText = "Track Request Details";

    if (isApprovalAlert) {
        subjectLine = "Action Required: Credit Limit Approval for " + identifier;
        headerTitle = "Pending Approval";
        introText = "A Non-Trade credit limit requires your commercial approval. Please review the details below.";
        themeAccent = "#003A70"; 
        portalPage = "uclm_non_trade_approval"; // Route Approvers Here
        buttonText = "Review Full Request in Portal";
    }
    // *** REQUEST CREATED / SUBMITTED NOTIFICATION ***
    else if (notifName.indexOf('Create') > -1 || notifName.indexOf('Submit') > -1) {
        subjectLine = "REQUEST SUBMITTED: Credit Limit for " + identifier;
        headerTitle = "Request Submitted";
        introText = "Your credit limit request has been successfully submitted and is now routing through the necessary approval channels. You can track its progress using the link below.";
        themeAccent = "#003A70"; 
    }
    else if (notifName.indexOf('Approved') > -1 || targetGr.getValue('state') == 'Approved') {
        subjectLine = "APPROVED: Credit Limit for " + identifier;
        headerTitle = "Request Approved";
        introText = "Good news! The credit limit request has been fully authorized and approved.";
        themeAccent = "#28a745"; 
    } 
    else if (notifName.indexOf('Rejected') > -1 || targetGr.getValue('state') == 'Rejected') {
        subjectLine = "DECLINED: Credit Limit for " + identifier;
        headerTitle = "Request Declined";
        introText = "This credit limit request has been declined. Please review the dashboard for comments or reasons.";
        themeAccent = "#C8102E"; 
    } 
    else if (notifName.indexOf('Comment') > -1 || notifName.indexOf('Activity') > -1) {
        subjectLine = "New Activity: Credit Limit Request for " + identifier;
        headerTitle = "New Comment Posted";
        introText = "A new comment or document has been added to this request.";
        themeAccent = "#F2A900"; 
        showCommentBlock = true;
    } 
    else {
        subjectLine = "Update: Credit Limit Request for " + identifier;
        headerTitle = "Request Update";
        introText = "There has been an update to this credit limit request.";
    }

    email.setSubject(subjectLine);

    var instanceUrl = gs.getProperty('glide.servlet.uri');
    // Appending dynamic URL parameters (Uses specific ID for Approvals, or Parent ID for Viewing)
    var portalLink = instanceUrl + 'uclm?id=' + portalPage + '&number=' + urlReqNum; 

    var logoUrl = "https://abgdev.service-now.com/x_birl3_clm.UltraTech.png"; 

    // ==========================================
    // 3.5 FETCH COMPLETE APPROVAL HISTORY ARRAY
    // ==========================================
    var historyList = [];
    var grApp = new GlideRecord('sysapproval_approver');
    grApp.addQuery('sysapproval', targetGr.getUniqueValue());
    grApp.addQuery('state', 'IN', 'approved,rejected');
    grApp.orderBy('sys_updated_on'); // Ordered chronologically from first action to last
    grApp.query();

    while (grApp.next()) {
        historyList.push({
            name: grApp.getDisplayValue('approver'),
            role: grApp.getValue('approval_journal_column') || 'Approver', // Fetching Role Name
            state: grApp.getValue('state') == 'approved' ? 'Approved' : 'Declined',
            color: grApp.getValue('state') == 'approved' ? '#28a745' : '#C8102E',
            date: grApp.getDisplayValue('sys_updated_on')
        });
    }

    // ==========================================
    // 4. GENERATE AESTHETIC HTML
    // ==========================================
    var html = '';

    html += '<table width="100%" cellpadding="0" cellspacing="0" border="0" style="background-color: #f0f3f5; padding: 40px 10px; font-family: \'Segoe UI\', Arial, sans-serif;">';
    html += '<tr><td align="center" valign="top">';

    // Main Email Card
    html += '<table width="600" align="center" cellpadding="0" cellspacing="0" border="0" style="background-color: #ffffff; border-radius: 8px; overflow: hidden; box-shadow: 0 8px 24px rgba(0,0,0,0.08);">';

    // Top Accent Border
    html += '<tr><td style="height: 6px; background-color: ' + themeAccent + ';"></td></tr>';

    // *** SPLIT HEADER: Logo Left / Text Right ***
    html += '<tr>';
    html += '<td style="padding: 30px 40px; background-color: #ffffff; border-bottom: 1px solid #f0f0f0;">';
    html += '<table width="100%" border="0" cellspacing="0" cellpadding="0"><tr>';

    html += '<td align="left" valign="middle">';
    html += '<img src="' + logoUrl + '" alt="UltraTech Cement" height="45" border="0" style="display: block; height: 45px; border: none; outline: none; text-decoration: none;" />';
    html += '</td>';

    // Right Align (Titles)
    html += '<td align="right" valign="middle">';
    html += '<h2 style="color: #003A70; margin: 0 0 4px 0; font-size: 20px; text-transform: uppercase; letter-spacing: 0.5px;">' + headerTitle + '</h2>';
    html += '<strong style="color: #888888; font-size: 14px; display: block;">Request ' + reqNum + '</strong>';
    html += '</td>';

    html += '</tr></table>';
    html += '</td>';
    html += '</tr>';

    html += '<tr>';
    html += '<td align="center" style="padding: 30px 40px;">';

    // Intro Text 
    html += '<p style="margin-top: 0; margin-bottom: 25px; font-size: 15px; line-height: 1.6; color: #444444; text-align: left;">' + introText + '</p>';

    // *** COMPLETE WORKFLOW HISTORY LIST TRAIL ***
    if (historyList.length > 0) {
        html += '<table width="100%" align="center" cellpadding="0" cellspacing="0" border="0" style="background-color: #fafafa; border: 1px solid #e2e8f0; border-radius: 6px; margin-bottom: 25px; padding: 16px 20px;">';
        html += '<tr><td align="left" style="font-size: 12px; color: #003A70; text-transform: uppercase; font-weight: bold; letter-spacing: 0.8px; padding-bottom: 10px; border-bottom: 1px solid #edf2f7;">📋 Workflow History Trail</td></tr>';
        html += '<tr><td style="padding-top: 12px;">';

        for (var h = 0; h < historyList.length; h++) {
            html += '<div style="font-size: 13.5px; line-height: 1.5; color: #333333; padding: 4px 0; text-align: left;">';
            html += '<span style="color: ' + historyList[h].color + '; font-weight: bold; margin-right: 6px;">✓ ' + historyList[h].state + ':</span>';
            html += '<strong>' + historyList[h].name + '</strong> <span style="font-size: 11px; color: #666666; text-transform: uppercase; margin-left: 4px;">(' + historyList[h].role + ')</span>';
            html += '<span style="color: #888888; font-size: 12px; float: right;">' + historyList[h].date + '</span>';
            html += '</div>';
        }

        html += '</td></tr></table>';
    }

    if (showCommentBlock) {
        var latestComment = targetGr.comments.getJournalEntry(1) || 'No comment text available.';
        var cleanComment = latestComment.substring(latestComment.indexOf('\n') + 1); 

        html += '<table width="100%" align="center" cellpadding="15" cellspacing="0" border="0" style="background-color: #fffdf5; border: 1px solid #F2A900; border-radius: 6px; margin-bottom: 25px;">';
        html += '<tr><td align="left" style="font-size: 14px; color: #333333; line-height: 1.5;">';
        html += '<strong style="color: #E65100; font-size: 12px; text-transform: uppercase; letter-spacing: 0.5px;">Latest Activity</strong><br><br>' + cleanComment.replace(/\n/g, '<br>');
        html += '</td></tr>';
        html += '</table>';
    }

    if (isDeviation) {
        html += '<table width="100%" align="center" cellpadding="12" cellspacing="0" border="0" style="background-color: #fff3f3; border: 1px solid #ffcccc; border-left: 4px solid #C8102E; border-radius: 4px; margin-bottom: 30px;">';
        html += '<tr><td align="left" style="font-size: 13px; color: #C8102E; line-height: 1.5;">';
        html += '<strong style="display: block; font-size: 14px; margin-bottom: 4px;">⚠ Executive Escalation Required</strong> The desired limit exceeds the system-calculated safe limit.';
        html += '</td></tr>';
        html += '</table>';
    }

    // Data Grid 
    html += '<table width="100%" align="center" cellpadding="12" cellspacing="0" border="0" style="margin-bottom: 30px; font-size: 14px; border-top: 1px solid #eeeeee;">';
    for (var i = 0; i < rowData.length; i++) {
        html += '<tr><td width="40%" align="left" style="border-bottom: 1px solid #eeeeee; color: #777777;">' + rowData[i].label + '</td>';
        html += '<td width="60%" align="right" style="border-bottom: 1px solid #eeeeee; color: #111111; font-weight: 500;">' + rowData[i].value + '</td></tr>';
    }
    html += '</table>';

    // Inject Outstanding Bucket for Site Level Approvals
    if (outstandingHtml !== '') {
        html += outstandingHtml;
    }

    // Justification Section 
    if (cleanJustification && cleanJustification !== 'No justification provided.') {
        html += '<div style="background-color: #f9f9f9; padding: 20px; border-radius: 6px; margin-bottom: 30px; text-align: left; border: 1px solid #eeeeee;">';
        html += '<span style="display: block; font-size: 11px; color: #888888; text-transform: uppercase; letter-spacing: 1px; margin-bottom: 10px;">Initiator Justification</span>';
        html += '<span style="font-size: 14px; line-height: 1.6; color: #444444; font-style: italic;">"' + cleanJustification + '"</span>';
        html += '</div>';
    }

    // ==========================================
    // 5. ATTACHMENT EXTRACTION
    // ==========================================
    if (isApprovalAlert) {
        var attGr = new GlideRecord('sys_attachment');
        attGr.addQuery('table_name', 'x_birl3_clm_batch_request');
        attGr.addQuery('table_sys_id', sysIdToView);
        attGr.query();

        if (attGr.hasNext()) {
            html += '<div style="margin-bottom: 35px; text-align: left;">';
            html += '<span style="display: block; font-size: 12px; color: #003A70; text-transform: uppercase; font-weight: bold; letter-spacing: 1px; margin-bottom: 10px; border-bottom: 2px solid #f0f0f0; padding-bottom: 5px;">Attached Documents</span>';

            while (attGr.next()) {
                var fileName = attGr.getValue('file_name');
                var fileSysId = attGr.getUniqueValue();
                var downloadUrl = instanceUrl + 'sys_attachment.do?sys_id=' + fileSysId;

                html += '<a href="' + downloadUrl + '" style="color: #0056b3; text-decoration: none; font-size: 13px; font-weight: bold; display: block; padding: 6px 0; border-bottom: 1px dashed #e0e0e0;">📄 ' + fileName + '</a>';
            }
            html += '</div>';
        }

        // --- DIRECT MAILTO APPROVAL BUTTONS ---
        var instanceEmailAddr = gs.getProperty('glide.email.user', 'abgdev@service-now.com');
        if (instanceEmailAddr.indexOf('@') === -1) {
            instanceEmailAddr += '@service-now.com';
        }

        // URL Encoded Subject and Body for mailto clients
        var watermarkText = email.watermark ? email.watermark : '';
        var mailToApprove = 'mailto:' + instanceEmailAddr + '?subject=Re: ' + encodeURIComponent(subjectLine) + ' - approve&body=' + encodeURIComponent('\n\n' + watermarkText);
        var mailToReject = 'mailto:' + instanceEmailAddr + '?subject=Re: ' + encodeURIComponent(subjectLine) + ' - reject&body=' + encodeURIComponent('Please provide your rejection comments here:\n\n\n\n' + watermarkText);

        html += '<table width="100%" border="0" cellspacing="0" cellpadding="0" style="margin-bottom: 15px;"><tr>';
        html += '<td align="center" style="padding-right: 8px; width: 50%;">';
        html += '<a href="' + mailToApprove + '" target="_blank" style="background-color: #28a745; font-size: 14px; font-family: \'Segoe UI\', Arial, sans-serif; color: #ffffff; text-decoration: none; padding: 12px 0; border-radius: 4px; display: block; font-weight: bold; text-align: center;">APPROVE</a>';
        html += '</td>';
        html += '<td align="center" style="padding-left: 8px; width: 50%;">';
        html += '<a href="' + mailToReject + '" target="_blank" style="background-color: #C8102E; font-size: 14px; font-family: \'Segoe UI\', Arial, sans-serif; color: #ffffff; text-decoration: none; padding: 12px 0; border-radius: 4px; display: block; font-weight: bold; text-align: center;">REJECT</a>';
        html += '</td>';
        html += '</tr></table>';
    }

    // Dynamic Call to Action Button (Fall-back to Portal)
    html += '<table width="100%" border="0" cellspacing="0" cellpadding="0"><tr><td align="center">';
    html += '<a href="' + portalLink + '" target="_blank" style="background-color: #003A70; font-size: 14px; font-family: \'Segoe UI\', Arial, sans-serif; color: #ffffff; text-decoration: none; padding: 12px 40px; border-radius: 4px; display: inline-block; font-weight: bold;">' + buttonText + '</a>';
    html += '</td></tr></table>';

    html += '</td>';
    html += '</tr>';

    // Footer
    html += '<tr>';
    html += '<td align="center" style="background-color: #f8f9fa; border-top: 1px solid #eeeeee; padding: 25px; font-size: 12px; color: #999999; line-height: 1.5;">';
    html += 'This is an automated notification from the <strong>UltraTech CLM Portal</strong>.<br>Please do not reply directly to this email.';
    html += '</td>';
    html += '</tr>';

    html += '</table>'; 
    html += '</td></tr></table>';

    template.print(html);

})(current, template, email, email_action, event);
